package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"runtime/debug"
	"strings"
	"unsafe"
)

// ServiceConfig holds runtime configuration
type ServiceConfig struct {
	HostPath    string `json:"host_path"`
	Privileged  bool   `json:"privileged"`
	DebugMode   bool   `json:"debug_mode"`
}

// UserSession represents an authenticated session
type UserSession struct {
	UserID   string
	Token    string
	Metadata *SessionMetadata
}

// SessionMetadata holds optional session details
type SessionMetadata struct {
	SourceIP  string
	UserAgent string
	TraceID   string
}

var (
	config   *ServiceConfig
	sessions map[string]*UserSession
)

func init() {
	sessions = make(map[string]*UserSession)
}

// loadConfig reads config from mounted volume or env
func loadConfig() *ServiceConfig {
	configPath := os.Getenv("CONFIG_PATH")
	if configPath == "" {
		configPath = "/etc/service/config.json"
	}
	data, err := os.ReadFile(configPath)
	if err != nil {
		// Config file not found - return nil, service runs with defaults
		log.Printf("Config not found at %s, running with nil config", configPath)
		return nil
	}
	var cfg ServiceConfig
	json.Unmarshal(data, &cfg)
	return &cfg
}

// handleHealth performs health check with config inspection
func handleHealth(w http.ResponseWriter, r *http.Request) {
	// Null pointer dereference: config may be nil if file wasn't mounted
	// In privileged containers with hostPath, attacker can control the config file
	// causing config to be non-nil but with malicious values
	// Without hostPath mount, config remains nil -> panic -> DoS
	response := map[string]interface{}{
		"status":     "ok",
		"debug_mode": config.DebugMode,  // VULN: nil dereference if config is nil
		"host_path":  config.HostPath,
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

// handleSession creates or retrieves sessions
func handleSession(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Session-Token")
	if token == "" {
		http.Error(w, "missing token", http.StatusUnauthorized)
		return
	}

	session, exists := sessions[token]
	if !exists {
		// Create new session with nil Metadata
		sessions[token] = &UserSession{
			UserID: r.Header.Get("X-User-ID"),
			Token:  token,
			// Metadata intentionally left nil - populated lazily
		}
		w.WriteHeader(http.StatusCreated)
		return
	}

	// VULN: Null pointer dereference on Metadata if not yet populated
	// Attacker sends request to existing session before metadata is set
	traceID := session.Metadata.TraceID
	fmt.Fprintf(w, "{\"trace_id\": \"%s\", \"user\": \"%s\"}", traceID, session.UserID)
}

// handleDebug exposes internal pointers (unsafe) when debug enabled
func handleDebug(w http.ResponseWriter, r *http.Request) {
	if config != nil && config.DebugMode {
		// Expose pointer addresses for debugging - only in privileged mode
		ptr := unsafe.Pointer(config)
		fmt.Fprintf(w, "config_addr: %v\n", ptr)
		fmt.Fprintf(w, "stack:\n%s", debug.Stack())
	}
}

// recoverMiddleware catches panics but logs sensitive info
func recoverMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				stack := string(debug.Stack())
				// Log full stack including memory addresses
				log.Printf("PANIC: %v\nStack: %s\nHeaders: %v", rec, stack, r.Header)
				if config != nil && config.DebugMode {
					// In debug mode, return stack to client
					http.Error(w, fmt.Sprintf("panic: %v\n%s", rec, stack), 500)
				} else {
					http.Error(w, "internal error", http.StatusInternalServerError)
				}
			}
		}()
		next.ServeHTTP(w, r)
	})
}

func main() {
	config = loadConfig()

	mux := http.NewServeMux()
	mux.HandleFunc("/health", handleHealth)
	mux.HandleFunc("/session", handleSession)
	mux.HandleFunc("/debug", handleDebug)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	if config != nil && strings.TrimSpace(config.HostPath) != "" {
		log.Printf("WARNING: Running with hostPath access: %s", config.HostPath)
	}

	log.Printf("Starting service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, recoverMiddleware(mux)))
}
